def rep(old,new,cnt=1):
    global s
    n=s.count(old)
    if n!=cnt:raise SystemExit('COUNT %d!=%d for: %s'%(n,cnt,old[:160]))
    s=s.replace(old,new)
def after(anchor,add,cnt=1):rep(anchor,anchor+add,cnt)
def before(anchor,add,cnt=1):rep(anchor,add+anchor,cnt)

